parameters.jsCode:
// The website sends events straight from the browser, so nothing in them is trusted.
// Orders are re-priced from the real menu; anything invalid stops here (no emails, no sheet row).
const MENU = {"flat-white":{"name":"Flat White","price":650},"spanish-latte":{"name":"Spanish Latte","price":720},"honey-cinnamon-latte":{"name":"Honey Cinnamon Latte","price":780},"iced-vanilla-oat-latte":{"name":"Iced Vanilla Oat Latte","price":760},"espresso":{"name":"Espresso","price":450},"americano":{"name":"Americano","price":500},"cappuccino":{"name":"Cappuccino","price":650},"butter-croissant":{"name":"Butter Croissant","price":480},"almond-croissant":{"name":"Almond Croissant","price":620},"chocolate-banana-bread":{"name":"Chocolate Banana Bread","price":540},"cinnamon-roll":{"name":"Cinnamon Roll","price":560},"avocado-toast":{"name":"Avocado Toast","price":950},"grilled-chicken-sandwich":{"name":"Grilled Chicken Sandwich","price":1150},"seasonal-granola-bowl":{"name":"Seasonal Granola Bowl","price":880},"morning-pairing":{"name":"Morning Pairing","price":1050}};
const LIMITS = { maxQuantity: 20, maxLines: 30, maxTotal: 100000 };
const clean = (v, n = 500) => String(v ?? '').replace(/[\u0000-\u001F\u007F]/g, ' ').trim().slice(0, n);

const body = $json.body ?? {};
const data = body.data ?? {};
if (body.event === 'order.created') {
  const lines = Array.isArray(data.items) ? data.items : [];
  if (!lines.length || lines.length > LIMITS.maxLines) throw new Error('Order has no items or too many lines');
  const items = lines.map((line) => {
    const product = MENU[line.id];
    const quantity = Number(line.quantity);
    if (!product) throw new Error('Unknown menu item: ' + line.id);
    if (!Number.isInteger(quantity) || quantity < 1 || quantity > LIMITS.maxQuantity) throw new Error('Bad quantity for ' + line.id);
    return { id: line.id, name: product.name, unitPrice: product.price, quantity, lineTotal: product.price * quantity };
  });
  const total = items.reduce((sum, i) => sum + i.lineTotal, 0);
  if (total > LIMITS.maxTotal) throw new Error('Order above online limit');
  const customer = { name: clean(data.customer?.name, 100), phone: clean(data.customer?.phone, 40), email: clean(data.customer?.email, 254) };
  if (customer.name.length < 2 || customer.phone.replace(/[^0-9]/g, '').length < 7) throw new Error('Missing customer name or phone');
  const fulfillment = data.fulfillment === 'delivery' ? 'delivery' : 'pickup';
  return [{ json: { body: { ...body, data: {
    id: clean(data.id, 40), createdAt: clean(data.createdAt, 40), status: 'received', customer, fulfillment,
    address: fulfillment === 'delivery' ? clean(data.address, 300) : '', notes: clean(data.notes),
    items, total, payment: 'Pay at pickup / on delivery',
    priceMismatch: Number(data.total) !== total,
  } } } }];
}
if (body.event === 'inquiry.created') {
  const inquiry = { id: clean(data.id, 40), createdAt: clean(data.createdAt, 40), name: clean(data.name, 100), email: clean(data.email, 254), category: clean(data.category, 40), message: clean(data.message, 2000) };
  if (!inquiry.name || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(inquiry.email) || inquiry.message.length < 10) throw new Error('Invalid inquiry');
  return [{ json: { body: { ...body, data: inquiry } } }];
}
throw new Error('Unknown event: ' + body.event);

